import{_t as e,it as t,n,rt as r}from"./chunks/framework.BM2esBXZ.js";var i=JSON.parse(`{"title":"介绍","description":"","frontmatter":{},"headers":[],"relativePath":"appendix/introduction.md","filePath":"appendix/introduction.md","lastUpdated":1794555917000}`),a={name:`appendix/introduction.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to “介绍”">​</a></h1><p>让 .NET 应用的边界清楚十年。</p><h2 id="序言" tabindex="-1">序言 <a class="header-anchor" href="#序言" aria-label="Permalink to “序言”">​</a></h2><p>写框架的人很多，能把一个框架维护十年的人很少。我希望 XiHan Framework 成为后者，所以它的每一条设计都在回答同一个问题：十年后这段代码还能不能用、还能不能换。</p><h2 id="名字的由来" tabindex="-1">名字的由来 <a class="header-anchor" href="#名字的由来" aria-label="Permalink to “名字的由来”">​</a></h2><p>曦，是清晨的第一缕光；寒，是冬日的清冷。我把这两个字放在一起给框架命名，是想让它像冬天的早晨：清冷、克制、不喧哗，但光一出来，一整天的工作就能看得清楚。框架、视图组件、基础应用和四款设计器共用「曦寒」这个前缀，组织叫曦寒懿（XiHanFun），寓意这一整套东西是一个有完整生态的家族，而不是零散的仓库。</p><h2 id="文档地址" tabindex="-1">文档地址 <a class="header-anchor" href="#文档地址" aria-label="Permalink to “文档地址”">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>地址</th></tr></thead><tbody><tr><td>开发框架（本站）</td><td><a href="https://framework.docs.xihanfun.com" target="_blank" rel="noreferrer">framework.docs.xihanfun.com</a></td></tr><tr><td>视图组件</td><td><a href="https://ui.docs.xihanfun.com" target="_blank" rel="noreferrer">ui.docs.xihanfun.com</a></td></tr><tr><td>基础应用</td><td><a href="https://basicapp.docs.xihanfun.com" target="_blank" rel="noreferrer">basicapp.docs.xihanfun.com</a></td></tr><tr><td>组织门户</td><td><a href="https://docs.xihanfun.com" target="_blank" rel="noreferrer">docs.xihanfun.com</a></td></tr></tbody></table><p>给 AI 编码助手读的纯文本版本见 <a href="/agents/llms">LLMs.txt</a>。</p><h2 id="开源地址" tabindex="-1">开源地址 <a class="header-anchor" href="#开源地址" aria-label="Permalink to “开源地址”">​</a></h2><table tabindex="0"><thead><tr><th>平台</th><th>地址</th></tr></thead><tbody><tr><td>GitHub（主库）</td><td><a href="https://github.com/XiHanFun/XiHan.Framework" target="_blank" rel="noreferrer">XiHanFun/XiHan.Framework</a></td></tr><tr><td>Gitee（同步备库）</td><td><a href="https://gitee.com/XiHanFun/XiHan.Framework" target="_blank" rel="noreferrer">XiHanFun/XiHan.Framework</a></td></tr><tr><td>GitCode（同步备库）</td><td><a href="https://gitcode.com/XiHanFun/XiHan.Framework" target="_blank" rel="noreferrer">XiHanFun/XiHan.Framework</a></td></tr><tr><td>NuGet</td><td><a href="https://www.nuget.org/profiles/XiHanFun" target="_blank" rel="noreferrer">XiHanFun</a></td></tr><tr><td>规范</td><td><a href="https://github.com/XiHanFun/framework-spec" target="_blank" rel="noreferrer">XiHanFun/framework-spec</a></td></tr><tr><td>Go SDK</td><td><a href="https://github.com/XiHanFun/framework-sdk-go" target="_blank" rel="noreferrer">XiHanFun/framework-sdk-go</a></td></tr></tbody></table><h2 id="框架包" tabindex="-1">框架包 <a class="header-anchor" href="#框架包" aria-label="Permalink to “框架包”">​</a></h2><p>框架由一组可以独立引用的 NuGet 包组成，全部共享一条版本线。包名由术语表与文法推出：<code>XiHan.Framework.&lt;领域&gt;[.&lt;角色&gt;]</code>。多数应用只需要记住三个组合包，再按需加协议适配器与 Provider：</p><table tabindex="0"><thead><tr><th>包</th><th>说明</th></tr></thead><tbody><tr><td><code>XiHan.Framework.Profiles.Minimal</code></td><td>原语层、内核、ASP.NET Core 宿主、内存本地化</td></tr><tr><td><code>XiHan.Framework.Profiles.Standard</code></td><td>Minimal 加领域模型，以及持久化、缓存、多租户、安全、消息五个子系统的抽象与内存默认实现</td></tr><tr><td><code>XiHan.Framework.Profiles.Full</code></td><td>Standard 加对象存储、调度、审计、工作流的默认实现，AI 工具目录，OpenTelemetry 导出与运行信息，HTTP、gRPC、MCP、CloudEvents 四种协议适配器</td></tr></tbody></table><p>常用的单包：</p><table tabindex="0"><thead><tr><th>类别</th><th>包</th></tr></thead><tbody><tr><td>原语与内核</td><td><code>Primitives</code>、<code>Kernel</code>、<code>Kernel.Generators</code>（源生成器）、<code>Kernel.Analyzers</code>（分析器）</td></tr><tr><td>协议</td><td><code>Protocols.Http</code>、<code>Protocols.Grpc</code>、<code>Protocols.Mcp</code>、<code>Protocols.CloudEvents</code></td></tr><tr><td>宿主</td><td><code>Hosting.AspNetCore</code>、<code>Hosting.CommandLine</code></td></tr><tr><td>持久化</td><td><code>Persistence.Abstractions</code>、<code>Persistence.InMemory</code>、<code>Persistence.EntityFrameworkCore</code>、<code>Persistence.SqlSugar</code>、<code>Persistence.Generators</code></td></tr><tr><td>缓存</td><td><code>Caching.Abstractions</code>、<code>Caching.InMemory</code>、<code>Caching.Redis</code>、<code>Caching.Hybrid</code>、<code>Caching.Remote</code></td></tr><tr><td>消息</td><td><code>Messaging.Abstractions</code>、<code>Messaging.InMemory</code>、<code>Messaging.RabbitMQ</code>、<code>Messaging.Kafka</code>、<code>Messaging.Redis</code></td></tr><tr><td>安全</td><td><code>Security.Abstractions</code>、<code>Security.InMemory</code>、<code>Security.Database</code>、<code>Security.Jwt</code>、<code>Security.OpenIdConnect</code>、<code>Security.Ip2Region</code></td></tr><tr><td>多租户</td><td><code>MultiTenancy.Abstractions</code>、<code>MultiTenancy.InMemory</code>、<code>MultiTenancy.Database</code></td></tr><tr><td>其他子系统</td><td><code>ObjectStorage.*</code>、<code>Scheduling.*</code>、<code>Workflow.*</code>、<code>Auditing.*</code>、<code>Localization.*</code>、<code>Configuration.*</code>、<code>Observability.*</code>、<code>AI.*</code></td></tr><tr><td>插件</td><td><code>Plugins.Protocol</code>、<code>Plugins.InProcess</code>、<code>Plugins.OutOfProcess</code>、<code>Plugins.Wasm</code></td></tr><tr><td>工具链</td><td><code>Cli</code>（<code>xihan</code> 工具）、<code>Testing</code>、各 <code>&lt;领域&gt;.Conformance</code></td></tr></tbody></table><p>完整清单与每个包的能力、配置节、主要类型见<a href="/packages/">包参考</a>。</p><h2 id="框架特点" tabindex="-1">框架特点 <a class="header-anchor" href="#框架特点" aria-label="Permalink to “框架特点”">​</a></h2><ul><li>微内核：内核只定义宿主、能力图谱、管道、诊断、安全原语、操作契约与插件抽象，公开类型有预算，第三方依赖为零。</li><li>按能力装配：特性在清单里按能力 ID 声明提供与依赖，内核在启动前求解整张图并打印；缺失、循环、冲突在启动期报错，不在第一次请求时报错。</li><li>固定阶段的管道：每次调用依次经过 Ingress 到 Egress 十一个阶段，认证、租户、授权、校验、幂等、事务都是阶段里的中间件，顺序确定、可打印、可单独测试。</li><li>一份契约多协议：操作用 <code>[Operation]</code> 声明一次，源生成器产出 JSON Schema；HTTP、gRPC、MCP 与命令行共用同一份 Schema、授权要求与错误码。</li><li>默认实现零外部依赖：每个子系统的抽象都配一个内存或文件系统实现，容量有界，通过一致性套件；换 Redis、EF Core、SqlSugar、RabbitMQ 只加包与配置，业务代码不变。</li><li>零反射与 Native AOT：原语层与内核不使用运行时反射，注册与 Schema 在编译期生成；示例应用以 Native AOT 发布作为 CI 冒烟项。</li><li>规范先于实现：原语、清单、上下文、管道阶段、协议映射与插件协议写在 XiHan Spec，Go SDK 与 .NET 参考实现通过同一套一致性向量。</li><li>边界由机器执行：依赖方向、包 ID 文法、命名空间、零反射、第三方类型泄漏、本地化文件齐全都由架构测试与分析器守护。</li></ul><h2 id="功能模块" tabindex="-1">功能模块 <a class="header-anchor" href="#功能模块" aria-label="Permalink to “功能模块”">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>内容</th><th>章节</th></tr></thead><tbody><tr><td>应用启动</td><td>装配、特性与清单、能力图谱、生命周期与健康、依赖注入、管道、调用上下文</td><td><a href="/startup/bootstrap">应用启动</a></td></tr><tr><td>配置</td><td>配置节、选项、配置目录热更新、资源绑定、远程配置与密钥</td><td><a href="/configuration/options">配置与选项</a></td></tr><tr><td>Web</td><td>ASP.NET Core 宿主、操作契约、HTTP 路由、端点、实时通信、OpenAPI</td><td><a href="/web/hosting">Web 应用开发</a></td></tr><tr><td>结果与校验</td><td><code>Result</code> 与 <code>Error</code>、错误码、Problem Details、契约校验</td><td><a href="/web/errors">结果与错误处理</a>与<a href="/web/validation">数据校验</a></td></tr><tr><td>数据</td><td>领域模型、仓储、工作单元、EF Core、SqlSugar、建表约定、连接、标识生成</td><td><a href="/persistence/domain">数据库操作指南</a></td></tr><tr><td>多租户</td><td>租户解析与隔离、分片与分库、数据库租户目录</td><td><a href="/multi-tenancy/resolution">SaaS 多租户</a></td></tr><tr><td>安全</td><td>认证、授权、RBAC 授予、条件引擎、IP 归属地、出站地址策略</td><td><a href="/security/authentication">安全鉴权</a></td></tr><tr><td>缓存</td><td>缓存读写、分布式锁、幂等、两级缓存、键管理</td><td><a href="/caching/basics">分布式缓存</a></td></tr><tr><td>消息</td><td>发布订阅、领域事件、发件箱、队列与流</td><td><a href="/messaging/pubsub">消息与事件</a></td></tr><tr><td>协议</td><td>gRPC、MCP、CloudEvents、命令行宿主</td><td><a href="/protocols/grpc">多协议暴露</a></td></tr><tr><td>本地化</td><td>消息键、十种内置区域、回退链、数据库翻译</td><td><a href="/common/localization">全球化和本地化</a></td></tr><tr><td>调度</td><td>作业、cron、集群分发、领导选举</td><td><a href="/scheduling/jobs">定时任务</a></td></tr><tr><td>工作流</td><td>定义、实例、用户任务、活动、补偿</td><td><a href="/workflow/definitions">工作流</a></td></tr><tr><td>对象存储</td><td>读写列举、分片上传、预签名、命名实例</td><td><a href="/object-storage/basics">对象存储</a></td></tr><tr><td>审计与可观测性</td><td>审计事件与查询、追踪、指标、日志、运行信息</td><td><a href="/common/auditing">审计</a>与<a href="/common/observability">日志与可观测性</a></td></tr><tr><td>AI</td><td>模型与对话、护栏、操作即工具、知识库</td><td><a href="/ai/chat">AI</a></td></tr><tr><td>弹性</td><td>截止时间、熔断、限流、并发上限</td><td><a href="/common/resilience">弹性与限流</a></td></tr><tr><td>插件</td><td>进程内、进程外、Wasm 三级隔离，Go SDK</td><td><a href="/plugins/overview">插件</a></td></tr><tr><td>部署</td><td>应用清单、<code>xihan pack</code>、Kubernetes</td><td><a href="/deployment/pack">托管、部署、发布</a></td></tr><tr><td>测试</td><td>测试宿主、一致性套件、架构门禁</td><td><a href="/testing/basics">测试指南</a></td></tr></tbody></table><h2 id="框架依赖" tabindex="-1">框架依赖 <a class="header-anchor" href="#框架依赖" aria-label="Permalink to “框架依赖”">​</a></h2><p>原语层、内核与全部抽象包不引用任何第三方库，只允许 <code>Microsoft.Extensions.*</code> 抽象包，内核另加 <code>System.Threading.RateLimiting</code>。第三方库只出现在按技术命名的 Provider 包里：</p><table tabindex="0"><thead><tr><th>类别</th><th>技术</th></tr></thead><tbody><tr><td>序列化</td><td>System.Text.Json 源生成</td></tr><tr><td>ORM Provider</td><td>EF Core、SqlSugar</td></tr><tr><td>缓存 Provider</td><td>StackExchange.Redis</td></tr><tr><td>消息 Provider</td><td>RabbitMQ.Client、Confluent.Kafka</td></tr><tr><td>对象存储 Provider</td><td>AWSSDK.S3</td></tr><tr><td>认证 Provider</td><td>Microsoft.IdentityModel.JsonWebTokens</td></tr><tr><td>AI</td><td>Microsoft.Extensions.AI、Microsoft.Extensions.VectorData</td></tr><tr><td>gRPC</td><td>Grpc.AspNetCore.Server</td></tr><tr><td>可观测性</td><td>OpenTelemetry</td></tr><tr><td>Wasm 插件</td><td>Wasmtime</td></tr></tbody></table><p>具体版本以仓库的 <code>framework/Directory.Packages.props</code> 为准。</p><h2 id="环境要求" tabindex="-1">环境要求 <a class="header-anchor" href="#环境要求" aria-label="Permalink to “环境要求”">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>要求</th></tr></thead><tbody><tr><td>SDK</td><td>.NET 10 SDK；构建框架源码时用仓库 <code>global.json</code> 锁定的功能带</td></tr><tr><td>编辑器</td><td>Visual Studio、JetBrains Rider 或 VS Code（C# Dev Kit）</td></tr><tr><td>测试运行器</td><td>Microsoft.Testing.Platform，由 <code>global.json</code> 启用</td></tr><tr><td>外部设施</td><td>默认实现不需要；Provider 按各自包页的说明</td></tr></tbody></table><h2 id="支持平台" tabindex="-1">支持平台 <a class="header-anchor" href="#支持平台" aria-label="Permalink to “支持平台”">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>支持</th></tr></thead><tbody><tr><td>运行环境</td><td>Windows、Linux、macOS；容器与 Kubernetes；Native AOT 发布</td></tr><tr><td>数据库</td><td>由持久化 Provider 决定：EF Core 支持的数据库，SqlSugar 支持的数据库；一致性套件在 SQLite 上运行，PostgreSQL、MySQL 与 Oracle 在 CI 里实测</td></tr><tr><td>缓存</td><td>内存、Redis、两级缓存、远程插件</td></tr><tr><td>消息</td><td>内存、RabbitMQ、Kafka、CloudEvents Webhook</td></tr><tr><td>对象存储</td><td>文件系统、Amazon S3 与兼容服务（MinIO、OSS、COS、R2）</td></tr><tr><td>远程配置</td><td>Nacos</td></tr><tr><td>协议</td><td>HTTP、gRPC、MCP、CloudEvents、命令行</td></tr><tr><td>插件语言</td><td>.NET、Go，以及任何能编译到 Wasm 或实现 gRPC 的语言</td></tr></tbody></table><p>Wasm 插件宿主在 Windows 上要求宿主可执行项目设置 <code>CETCompat=false</code>。</p><h2 id="关于性能" tabindex="-1">关于性能 <a class="header-anchor" href="#关于性能" aria-label="Permalink to “关于性能”">​</a></h2><p>内核的预算是：冷启动在 ASP.NET Core 基线之上，JIT 下不超过 100 毫秒、Native AOT 下少于 50 毫秒，单个中间件的管道执行少于 0.1 毫秒，空应用里框架额外占的常驻内存不超过 15 MB，原语层加内核的包少于 500 KB，基准回归超过 5% 阻断。基准项目在仓库的 <code>framework/benchmarks</code> 下，可以本地运行；我不贴测试图，因为它们只在特定机器上成立。</p><h2 id="贡献代码" tabindex="-1">贡献代码 <a class="header-anchor" href="#贡献代码" aria-label="Permalink to “贡献代码”">​</a></h2><p>框架遵循 MIT 协议，欢迎提交 Pull Request 与 Issue。流程、代码规范与门禁见<a href="/appendix/contributing">贡献指南</a>。感谢每一位为框架贡献代码、文档与一致性向量的朋友。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="/getting-started/installation">环境与安装</a>：开始使用</li></ul>`,36)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};